	"github.com/go-sql-driver/mysql"
)

type connector struct {
	dsn string
}

func (c connector) Connect(context.Context) (driver.Conn, error)...", "path": "doc/md/sql-integration.md", "retrieval_provenance": {"blob_sha": "50c75e795641150634f9f334da9d1fca1ca461ce", "discovery_source": "base_sha_tree", "excluded_artifact_paths": 8, "generator_pool_policy": "base_sha_broad_bounded_doc_pool_v2", "max_generator_doc_chars_per_file": 1500, "max_generator_doc_files": 12, "method": "base_sha_tree_documentation_discovery_v2", "path": "doc/md/sql-integration.md", "selection_policy": "prefer_first_party_human_docs_then_root_project_docs_then_reference_plus_neutral_code_path_affinity", "selection_rank": 11, "selection_score": [45, 4, 5, 3, "doc/md/sql-integration.md"], "tree_discovery_succeeded": true, "tree_ref": "b91f8daf0e3267a1c7818f8120e83a36d56054b3", "truncated": false, "truncated_excerpt": true, "used_docs_changed_files": false}, "source_ref": "b91f8daf0e3267a1c7818f8120e83a36d56054b3"}, {"blob_sha": "79fcd19280c0e1e6d2d4f4f8f3df7ae0dee202f9", "excerpt": "---
id: tutorial-todo-gql-schema-generator
title: Schema Generator
sidebar_label: Schema Generator
---

In this section, we will continue the [GraphQL example](tutorial-todo-gql.mdx) by explaining how to generate a
type-safe GraphQL schema from our `ent/schema`.

### Configure Ent

Go to your `ent/entc.go` file, and add the highlighted line (extension options):

```go {5} title="ent/entc.go"
func main() {
	ex, err := entgql.NewExtension(
		entgql.WithWhereInputs(true),
		entgql.WithConfigPath("../gqlgen.yml"),
		entgql.WithSchemaGenerator(),
		entgql.WithSchemaPath("../ent.graphql"),
	)
	if err != nil {
		log.Fatalf("creating entgql extension: %v", err)
	}
	opts := []entc.Option{
		entc.Extensions(ex),
		entc.TemplateDir("./template"),
	}
	if err := entc.Generate("./schema", &gen.Config{}, opts...); err != nil {
		log.Fatalf("running ent codegen: %v", err)
	}
} 
```

The `WithSchemaGenerator` option enables the GraphQL schema generation.

### Add Annotations To `Todo` Schema

The `entgql.RelayConnection()` annotation is used to generate the Relay `<T>Edge`, `<T>Connection`, and `PageInfo` types for the `Todo` type.

The `entgql.QueryField()` annotation is used to generate the `todos` field in the `Query` type.

