+// DeprecatedFields returns all deprecated fields of the type.
+func (t Type) DeprecatedFields() []*Field {
+	fs := make([]*Field, 0, len(t.Fields))
+	for _, f := range t.Fields {
+		if f.IsDeprecated() {
+			fs = append(fs, f)
+		}
+	}
+	return fs
+}
