+
+func decodeLink(jl *Link) *tracepb.Span_Link {
+	return &tracepb.Span_Link{
+		TraceId:                jl.TraceID[:],
+		SpanId:                 jl.SpanID[:],
+		TraceState:             jl.TraceState,
+		Attributes:             decodeKeyValues(jl.Attributes),
+		DroppedAttributesCount: jl.DroppedAttributesCount,
+		Flags:                  jl.Flags,
+	}
