+
+func decodeKeyValues(jkvs []*KeyValue) []*commonpb.KeyValue {
+	if len(jkvs) == 0 {
+		return nil
+	}
+	kvs := make([]*commonpb.KeyValue, len(jkvs))
+	for i, jkv := range jkvs {
+		kvs[i] = &commonpb.KeyValue{
+			Key:   jkv.Key,
+			Value: decodeAnyValue(jkv.Value),
+		}
+	}
+	return kvs
